INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist /64 der Standardpräfix für jedes LAN?', 2, '[{"text": "Ja", "correct": true, "because": "Empfohlen für Subnetze"}, {"text": "Nein", "correct": false, "because": "Allgemein akzeptiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits umfasst ein /48-Präfix für Organisationen?', 3, '[{"text": "48", "correct": true, "because": "Definiert Netzwerkanteil"}, {"text": "64", "correct": false, "because": "LAN-Standard"}, {"text": "128", "correct": false, "because": "Gesamtlänge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Präfix wähle ich für ein kleines Netzwerk?', 4, '[{"text": "/64", "correct": true, "because": "Standard für LAN"}, {"text": "/48", "correct": false, "because": "Für größere Strukturen"}, {"text": "/128", "correct": false, "because": "Einzelgerät"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /48 ist für Organisationen. b) /64 erlaubt Subnetze.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) ist Standard, b) ist möglich"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines /48-Präfix?', 5, '[{"text": "Einzelgeräte", "correct": true, "because": "Für größere Netze"}, {"text": "Subnetzanzahl", "correct": false, "because": "Kern der Planung"}, {"text": "Bitanzahl", "correct": false, "because": "Definiert Präfix"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /64 für Organisationen zu klein ist?', 2, '[{"text": "Ja", "correct": true, "because": "Nur ein Subnetz"}, {"text": "Nein", "correct": false, "because": "/48 bietet mehr Flexibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Präfix nutze ich für eine Firma mit mehreren Standorten?', 3, '[{"text": "/48", "correct": true, "because": "Erlaubt viele Subnetze"}, {"text": "/64", "correct": false, "because": "Zu klein für Organisation"}, {"text": "/32", "correct": false, "because": "Zu groß für typische Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften haben Standardpräfixe?', 5, '[{"text": "/64 für LAN", "correct": true, "because": "Typisch für Subnetze"}, {"text": "/48 für Organisationen", "correct": true, "because": "Bietet Subnetzflexibilität"}, {"text": "/128 für Subnetze", "correct": false, "because": "Nur Einzeladresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) /64 ist für SLAAC nötig. b) /48 ist nur für ISPs. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) gilt auch für Firmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen /64-Präfix?', 4, '[{"text": "Netzwerkanteil", "correct": false, "because": "Definiert Subnetz"}, {"text": "Interface-ID", "correct": false, "because": "Rest der Adresse"}, {"text": "Globale Subnetze", "correct": true, "because": "Nur ein Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist /48 für ein LAN zu groß?', 2, '[{"text": "Ja", "correct": true, "because": "/64 ist ausreichend"}, {"text": "Nein", "correct": false, "because": "Aber nicht üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Präfixe sind für typische Netzwerke wichtig?', 4, '[{"text": "/64", "correct": true, "because": "LAN-Standard"}, {"text": "/48", "correct": true, "because": "Organisationsnetze"}, {"text": "/96", "correct": false, "because": "Nicht Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass /64 keine Subnetze erlaubt. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Kann weiter aufgeteilt werden"}, {"text": "Ja", "correct": false, "because": "Flexibel nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wahl eines /48-Präfix?', 3, '[{"text": "Subnetzflexibilität", "correct": true, "because": "Viele Subnetze möglich"}, {"text": "Einzelgeräte", "correct": false, "because": "Nicht der Fokus"}, {"text": "Kürzeste Adresse", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /64 ist für kleine Netze. b) /48 ist nicht routbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, routbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Standardpräfixe?', 5, '[{"text": "/64: SLAAC-Kompatibilität", "correct": true, "because": "Autokonfiguration"}, {"text": "/48: Viele Subnetze", "correct": true, "because": "Organisationsflexibilität"}, {"text": "/64: Globale Reichweite", "correct": false, "because": "Nur ein Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem /64-Präfix unwichtig?', 3, '[{"text": "Netzwerkanteil", "correct": false, "because": "Definiert Subnetz"}, {"text": "Interface-ID", "correct": false, "because": "Rest der Adresse"}, {"text": "Mehrere Subnetze", "correct": true, "because": "Nur eines möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist /48 für ein LAN üblich?', 2, '[{"text": "Nein", "correct": true, "because": "/64 ist Standard"}, {"text": "Ja", "correct": false, "because": "Eher für Organisationen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /64 für große Firmen reicht?', 3, '[{"text": "Nein", "correct": true, "because": "/48 bietet mehr Subnetze"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Präfix wähle ich für ein Subnetz mit Autokonfiguration?', 4, '[{"text": "/64", "correct": true, "because": "SLAAC erfordert es"}, {"text": "/48", "correct": false, "because": "Zu groß für ein Subnetz"}, {"text": "/56", "correct": false, "because": "Nicht SLAAC-Standard"}]');
